import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BtwMessage } from '../types'

const PANE = 'btw'
const thread = atom({ plugin: 'btw-chat', key: 'thread' } as const, [])
const isThinking = atom({ plugin: 'btw-chat', key: 'isThinking' } as const, false)

const openPane = ($: EngineInterface) =>
  $.ui.open({ id: PANE, title: 'btw', focus: true, closeOnEscape: true })

export const composeForkPrompt = (history: readonly BtwMessage[], question: string) =>
  [
    'This is a side conversation ("btw") the person is having with you while the main task goes on.',
    'Answer from what you already know of this session. You cannot use tools here, and this exchange never enters the main thread.',
    'Be brief and conversational.',
    ...(history.length > 0
      ? ['', 'The side conversation so far:', ...history.map(m => `${m.role === 'you' ? 'Person' : 'You'}: ${m.text}`)]
      : []),
    '',
    `Person: ${question}`,
  ].join('\n')

const ask = async ($: EngineInterface, question: string) => {
  const text = question.trim()
  if (text === '' || (await read($, isThinking))) return

  const history = await read($, thread)
  await update($, thread, list => [...list, { role: 'you' as const, text }])
  await update($, isThinking, () => true)

  const reply = await $.model.fork({ prompt: composeForkPrompt(history, text) })
  const answer = reply.isAnswered ? reply.text : `_(no reply: ${reply.reason})_`

  await update($, thread, list => [...list, { role: 'claude' as const, text: answer }])
  await update($, isThinking, () => false)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'btw-chat',
      description: 'Side conversation that never interrupts the main session (`clear` resets the thread)',
    })
    return next(e)
  })

  on('command.run', { command: 'btw-chat' }, async ($, e) => {
    if (e.args.trim() === 'clear') {
      await update($, thread, () => [])
      return { text: 'btw thread cleared.' }
    }
    await openPane($)
    if (e.args.trim() !== '') void ask($, e.args)
    return { text: 'btw pane opened.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    if (e.surface === 'mobile') return next(e)
    const { Box, Text, Markdown, Input } = $.ui.resolve(e)
    const list = await read($, thread)
    const thinking = await read($, isThinking)

    return (
      <Box flexDirection="column">
        {list.length === 0 && <Text dimColor>Ask anything; the main session keeps working.</Text>}
        {list.map(m =>
          m.role === 'you' ? <Text bold>› {m.text}</Text> : <Markdown text={m.text} />,
        )}
        {thinking && <Text dimColor>thinking…</Text>}
        <Input
          key="btw-input"
          placeholder={thinking ? 'waiting for the reply…' : 'btw…'}
          submitLabel="send"
          value=""
          autoFocus
          onSubmit={(value: string) => void ask($, value)}
        />
      </Box>
    )
  })
}

